const N=70;const parts=[];for(let i=0;i<N;i++){parts.push({x:Math.random()*W(),y:Math.random()*H(),r:1+Math.random()*2.2,baseA:0.15+Math.random()*0.35,phase:Math.random()*Math.PI*2,speed:0.15+Math.random()*0.25,drift:(Math.random()-0.5)*0.15,hueIdx:Math.floor(Math.random()*PALETTE.length),zone:Math.random()<0.5?'top':'bottom'});}
function hexToRgb(h){h=h.replace('#','');const n=parseInt(h,16);return [(n>>16)&255,(n>>8)&255,n&255];}
const rgbs=PALETTE.map(hexToRgb);
let t=0;
function frame(){
  t+=0.008;
  const w=W(),h=H();
  const cx=w/2, cy=h/2;
  const safeR=Math.min(w,h)*0.26;
  for(const p of parts){
    let targetY = p.zone==='top'? h*0.18 : h*0.82;
    let dy = (p.y - targetY);
    p.y += Math.sin(t*p.speed+p.phase)*0.25 + (p.zone==='top'?0.12:-0.12);
    p.x += p.drift + Math.sin(t*0.5+p.phase)*0.08;
    if(p.x<0)p.x=w; if(p.x>w)p.x=0;
    if(p.y<0)p.y=h; if(p.y>h)p.y=0;
    const dist = Math.hypot(p.x-cx,p.y-cy);
    let centerFade = 1;
    if(dist<safeR){ centerFade = Math.max(0, dist/safeR); centerFade = centerFade*centerFade; }
    const a = p.baseA * (0.55+0.45*Math.sin(t*1.3*p.speed+p.phase)) * centerFade;
    if(a<=0.01) continue;
    const c=rgbs[p.hueIdx];
    const grad=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r*6);
    grad.addColorStop(0, `rgba(${c[0]},${c[1]},${c[2]},${a})`);
    grad.addColorStop(1, `rgba(${c[0]},${c[1]},${c[2]},0)`);
    ctx.beginPath();
    ctx.fillStyle=grad;
    ctx.arc(p.x,p.y,p.r*6,0,Math.PI*2);
    ctx.fill();
    ctx.beginPath();
    ctx.fillStyle=`rgba(255,255,255,${a*0.9})`;
    ctx.arc(p.x,p.y,p.r*0.6,0,Math.PI*2);
    ctx.fill();
  }
  // тонкие нити света сверху вниз по краям
  ctx.save();
  ctx.globalAlpha=0.12+0.05*Math.sin(t*0.9);
  ctx.strokeStyle=`rgba(${rgbs[1][0]},${rgbs[1][1]},${rgbs[1][2]},0.5)`;
  ctx.lineWidth=1;
  for(let i=0;i<5;i++){
    const x0 = w*(0.08+i*0.04);
    ctx.beginPath();
    ctx.moveTo(x0, h*0.05);
    ctx.bezierCurveTo(x0+10*Math.sin(t+i), h*0.3, x0-10*Math.sin(t*0.7+i), h*0.6, x0+6*Math.sin(t*1.1+i), h*0.95);
    ctx.stroke();
  }
  ctx.restore();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
